def compute(vars):
    old_balance = vars["v1"]
    new_balance = vars["v2"]

    if old_balance == 0:
        return None

    decline = old_balance - new_balance
    percent_decline = decline / old_balance * 100

    return {
        "value": percent_decline,
        "trace": {
            "old_balance": old_balance,
            "new_balance": new_balance,
            "decline": decline,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
